// We overload the LSB of the page pointer to indicate whether it's
// a valid sg entry, or whether it points to the start of a new scatterlist.
// Those low bits are there for everyone! (thanks mason :-)
fn find_next_netdev_feature(mut feature: u64, start: u64) -> i32 {
// like BITMAP_LAST_WORD_MASK() for u64
// this sets the most significant 64 - start to 0.
let __v1: u64 = feature & 18446744073709551615u64 >> (start.wrapping_neg() & (core::mem::size_of::<u64>() as u64).wrapping_mul(8).wrapping_sub(1));
feature = __v1;
fls64(feature).wrapping_sub(1)
}

// This goes for the MSB to the LSB through the set feature bits,
// mask_addr should be a u64 and bit an int
// Segmentation offload feature mask
// List of IP checksum features. Note that NETIF_F_HW_CSUM should not be
// set in features when NETIF_F_IP_CSUM or NETIF_F_IPV6_CSUM are set--
// this would be contradictory
// If one device supports one of these features, then enable them
// for all in netdev_increment_features.
// If one device doesn't support one of these features, then disable it
// for all in netdev_increment_features.
// If upper/master device has these features disabled, they must be disabled
// on all lower/slave devices as well.
// changeable features with no special hardware requirements
// Changeable features with no special hardware requirements that defaults to off.
// virtual device features
fn netdev_base_features(mut features: u64) -> u64 {
let __v0: u64 = features;
features = __v0 & !(__NETIF_F_BIT!(16i32) | __NETIF_F_BIT!(20i32) | __NETIF_F_BIT!(18i32) | __NETIF_F_BIT!(19i32) | __NETIF_F_BIT!(35i32) | __NETIF_F_BIT!(30i32) | __NETIF_F_BIT!(33i32) | __NETIF_F_BIT!(34i32) | __NETIF_F_BIT!(17i32) | __NETIF_F_BIT!(0i32) | __NETIF_F_BIT!(5i32) | __NETIF_F_BIT!(6i32) | __NETIF_F_BIT!(10i32));
let __v2: u64 = features;
features = __v2 | (__NETIF_F_BIT!(41i32) | __NETIF_F_BIT!(21i32));
features
}

